<?php require 'includes/init.php'; $st=Database::conn()->prepare('SELECT * FROM routes WHERE id=?');$st->execute([(int)($_GET['route']??0)]);$r=$st->fetch();$date=$_GET['date']??'';$trips=$r?Bus::search($r['origin'],$r['destination'],$date):[]; include 'includes/header.php'; ?>
<main class="page"><div class="wrap"><div class="steps"><div class="step active"><b>1</b>Search</div><div class="step"><b>2</b>Select Bus</div><div class="step"><b>3</b>Choose Seat</div><div class="step"><b>4</b>Payment</div><div class="step"><b>5</b>Confirmation</div></div><div class="card search-summary"><div><b><?= $r?e($r['origin'].' → '.$r['destination']):'Route not found' ?></b><div class="meta"><?= e($date) ?></div></div><a class="btn outline" href="index.php">Edit Search</a></div><div class="filters"><span class="chip active">All Buses</span><span class="chip">AC</span><span class="chip">Non-AC</span><span class="chip">Earliest</span></div><div class="bus-list"><?php if(!$trips): ?><div class="card panel">No buses found for that date. <a href="index.php">Try another search</a>.</div><?php endif; ?><?php foreach($trips as $i=>$t): ?><div class="card bus-row"><img src="images/bus <?= (($i%11)+1) ?>.jpg" alt="Bus"><div><h3><?= e($t['bus_name']) ?></h3><div class="meta"><?= e($t['bus_type']) ?> • <?= (int)$t['total_seats'] ?> Seats<br><?= date('g:i A',strtotime($t['departure_time'])) ?><?= $t['arrival_time']?' - '.date('g:i A',strtotime($t['arrival_time'])):'' ?></div><div class="badges"><span class="badge"><?= stripos($t['bus_type'],'AC')!==false?'AC':'Bus' ?></span><span class="badge"><?= (int)$t['seats_left'] ?> seats left</span></div></div><div class="fare"><strong><?= naira($t['price']) ?></strong><small>per seat</small><br><?php if($t['seats_left']>0): ?><a class="btn primary" href="details.php?trip=<?= (int)$t['id'] ?>">View Bus</a><?php else: ?><span class="status cancel">Sold out</span><?php endif; ?></div></div><?php endforeach; ?></div></div></main><?php include 'includes/footer.php'; ?>
